/*! bridgey site samples (build 時に site.js と views から生成) */
window.__BRIDGEY_SAMPLES = {"homeDemo":{"js":"const UNIT_PRICE = 1100;\nconst quantity = $$.state(1);\n\nconst total = $$.computed(() => quantity() * UNIT_PRICE);\n\n$el.find(\"@qty\").text(quantity);\n$el.find(\"@total\").text(total, $$.money);\n\n$el.find(\"@inc\").click(() => quantity((current) => current + 1));\n$el.find(\"@dec\").click(() => quantity((current) => Math.max(1, current - 1)));\n\n$el.find(\"@free\").when(() => quantity() >= 3);\n$el.find(\"@bar\").vars({\n  progress: () => `${Math.min(100, quantity() * 20)}%`,\n});","html":"<div class=\"card\" data-component=\"home-demo\">\n        <div class=\"demo-row\">\n          <span>数量</span>\n          <span class=\"demo-qty\">\n            <button data-brg=\"dec\" aria-label=\"減らす\">−</button>\n            <b data-brg=\"qty\"></b>\n            <button data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n          </span>\n        </div>\n        <div class=\"demo-row\">\n          <span>合計</span>\n          <span class=\"demo-price\"><span data-brg=\"total\"></span><small>円</small></span>\n        </div>\n        <p class=\"demo-free\" data-brg=\"free\">3個以上で送料無料になりました</p>\n        <div class=\"demo-bar\" data-brg=\"bar\"><i></i></div>\n      </div>"},"counter":{"js":"const MAX_QUANTITY = 20;\nconst UNIT_PRICE = 1100;\n\n// 状態はこの1つだけ\nconst quantity = $$.state(1);\n\n// ここから下は全部「導出」。どこにも代入していない\nconst doubled = $$.computed(() => quantity() * 2);\nconst total = $$.computed(() => quantity() * UNIT_PRICE);\nconst isBulk = $$.computed(() => quantity() >= 10);\nconst isMax = $$.computed(() => quantity() >= MAX_QUANTITY);\n\n$el.find(\"@cnt-n\").text(quantity);\n$el.find(\"@cnt-doubled\").text(doubled);\n$el.find(\"@cnt-total\").text(total, $$.money);\n\n$el.find(\"@cnt-inc\").click(() => {\n  quantity((current) => Math.min(MAX_QUANTITY, current + 1));\n});\n$el.find(\"@cnt-dec\").click(() => {\n  quantity((current) => Math.max(1, current - 1));\n});\n$el.find(\"@cnt-reset\").click(() => quantity(1));\n\n$el.find(\"@cnt-inc\").disabled(isMax);\n$el.find(\"@cnt-dec\").disabled(() => quantity() <= 1);\n$el.find(\"@cnt-over\").when(isBulk);\n$el.find(\"@cnt-limit\").when(isMax);","html":"<div class=\"card\" data-component=\"ex-counter\">\n          <div class=\"ex-total\" style=\"border:0;padding-top:0\">\n            <span>数量</span>\n            <span class=\"demo-qty\" style=\"display:inline-flex;align-items:center;gap:14px\">\n              <button type=\"button\" data-brg=\"cnt-dec\">−</button>\n              <b data-brg=\"cnt-n\" style=\"min-width:2em;text-align:center;font-size:20px\"></b>\n              <button type=\"button\" data-brg=\"cnt-inc\">＋</button>\n            </span>\n          </div>\n          <div class=\"ex-total\"><span>2倍した値</span><span data-brg=\"cnt-doubled\"></span></div>\n          <div class=\"ex-total\"><span>合計（単価 1,100円）</span>\n            <strong class=\"ex-price\"><span data-brg=\"cnt-total\"></span><small>円</small></strong></div>\n          <p class=\"good\" data-brg=\"cnt-over\">10個以上のまとめ買いです</p>\n          <p class=\"ex-hidden-note\" data-brg=\"cnt-limit\">上限は20個です</p>\n          <div class=\"ex-inline\">\n            <button type=\"button\" class=\"btn ghost\" data-brg=\"cnt-reset\" style=\"font-size:13px\">リセット</button>\n          </div>\n        </div>"},"exampleForm":{"js":"const options = $$.state(OPTIONS.slice());\nconst plan = $el.find(\"@plan\").group();\n\n// オプション一覧（行の DOM は使い回されるのでチェックが消えない）\n$el.find(\"@opts\").repeat(options, {\n  key: (option) => option.id,\n  tpl: \"@opt-tpl\",\n  render: ($row, option) => {\n    $row.find(\"@opt-name\").text(option.name);\n    $row.find(\"@opt-price\").text(option.price, $$.money, \"円/月\");\n    $row.find(\"@opt-check\").attr(\"value\", option.id);\n  },\n});\n\n// 選択を1つの state にして、合計は導出する（代入する場所を作らない）\n// 後からオプションが増えても、この state に自動で参加する（張り直しは要らない）\nconst selectedIds = $el.find(\"@opt-check\").group();\n\nconst optionTotal = $$.computed(() => {\n  const priceOf = new Map(options().map((option) => [option.id, option.price]));\n\n  return selectedIds().reduce((sum, id) => sum + (priceOf.get(id) ?? 0), 0);\n});\n\n$el.find(\"@opt-total\").text(optionTotal, $$.money);\n\n// 法人のときだけ会社名を表示し、同じ条件で必須にする\nconst isCorporate = $$.computed(() => plan() === \"corp\");\n$el.find(\"@corp-box\").when(isCorporate);\n\nconst signupForm = $el.find(\"@form\").form({\n  company: {\n    required: isCorporate,\n    message: \"会社名を入力してください\",\n  },\n  tel: {\n    pattern: /^0\\d{9,10}$/,\n    message: \"電話番号の形式が正しくありません（ハイフンなし）\",\n  },\n  confirm: {\n    same: \"password\",\n    message: \"パスワードが一致しません\",\n  },\n  agree: {\n    required: true,\n    message: \"規約への同意が必要です\",\n  },\n  // promo は required だが画面に出ていない → 検証されない（CV を守る）\n});\n\n// 郵便番号の自動整形（日本語変換中は書き戻さないので変換が壊れない）\nconst zipCode = $el.find(\"#ex-zip\").state(\"\");\n\n$el.find(\"#ex-zip\").val(() => {\n  const digits = String(zipCode()).replace(/[^0-9]/g, \"\").slice(0, 7);\n\n  return digits.length > 3\n    ? `${digits.slice(0, 3)}-${digits.slice(3)}`\n    : digits;\n});\n\n$el.find(\"@err-summary\").text(signupForm.errorCount, (count) => {\n  return count ? `未入力・不備が${count}件あります` : \"\";\n});\n$el.find(\"@submit\").disabled(signupForm.submitting);\n$el.find(\"@done\").when(() => {\n  return signupForm.submitted() && signupForm.valid() && !signupForm.submitting();\n});\n\nreturn { form: signupForm, options };","html":"<div class=\"card\" data-component=\"ex-form\">\n        <form class=\"ex-form\" data-brg=\"form\">\n          <div class=\"ex-row\">\n            <label>お申し込み種別</label>\n            <div class=\"ex-inline\">\n              <label><input type=\"radio\" name=\"plan\" value=\"personal\" data-brg=\"plan\" checked> 個人</label>\n              <label><input type=\"radio\" name=\"plan\" value=\"corp\" data-brg=\"plan\"> 法人</label>\n            </div>\n          </div>\n\n          <div class=\"ex-row\" data-brg=\"corp-box\">\n            <label for=\"ex-company\">会社名（法人のときだけ必須）</label>\n            <input id=\"ex-company\" name=\"company\" type=\"text\" autocomplete=\"organization\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-mail\">メールアドレス（必須）</label>\n            <input id=\"ex-mail\" name=\"mail\" type=\"email\" required autocomplete=\"email\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-tel\">電話番号（必須・ハイフンなし）</label>\n            <input id=\"ex-tel\" name=\"tel\" type=\"tel\" required autocomplete=\"tel\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-zip\">郵便番号（入力すると自動でハイフンが入ります）</label>\n            <input id=\"ex-zip\" name=\"zip\" type=\"text\" autocomplete=\"postal-code\" placeholder=\"1000001\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label for=\"ex-pass\">パスワード（8文字以上）</label>\n            <input id=\"ex-pass\" name=\"password\" type=\"password\" minlength=\"8\">\n          </div>\n          <div class=\"ex-row\">\n            <label for=\"ex-pass2\">パスワード（確認）</label>\n            <input id=\"ex-pass2\" name=\"confirm\" type=\"password\">\n          </div>\n\n          <div class=\"ex-row\">\n            <label>オプション</label>\n            <ul class=\"ex-opts\" data-brg=\"opts\"></ul>\n            <template data-brg=\"opt-tpl\">\n              <li data-brg=\"opt-row\">\n                <input type=\"checkbox\" data-brg=\"opt-check\">\n                <span data-brg=\"opt-name\" style=\"flex:1\"></span>\n                <span data-brg=\"opt-price\" class=\"ex-hidden-note\"></span>\n              </li>\n            </template>\n          </div>\n\n          <!-- 画面に出ていない必須項目。旧来のやり方だとここで CV が死ぬ -->\n          <div data-brg=\"hidden-box\" style=\"display:none\">\n            <label for=\"ex-promo\">キャンペーンコード（画面に出ていない必須項目）</label>\n            <input id=\"ex-promo\" name=\"promo\" type=\"text\" required>\n          </div>\n\n          <div class=\"ex-inline\">\n            <label><input type=\"checkbox\" name=\"agree\" data-brg=\"agree\" required> 規約に同意する（必須）</label>\n          </div>\n\n          <div class=\"ex-total\">\n            <span>オプション合計</span>\n            <strong class=\"ex-price\"><span data-brg=\"opt-total\">0</span><small>円/月</small></strong>\n          </div>\n\n          <div class=\"ex-total\" style=\"border:0\">\n            <span class=\"bad\" data-brg=\"err-summary\"></span>\n            <button type=\"submit\" class=\"btn primary\" data-brg=\"submit\">この内容で申し込む</button>\n          </div>\n          <p class=\"good\" data-brg=\"done\">送信しました</p>\n        </form>\n      </div>"},"cart":{"js":"const FREE_SHIPPING_FROM = 30000;\nconst SHIPPING_FEE = 550;\nconst TAX_RATE = 0.1;\nconst COUPON_RATE = 0.1;\n\nconst items = $$.state(CART_ITEMS.map((item) => ({ ...item })));\nconst useCoupon = $el.find(\"@coupon\").state(false);\n\n// ここから下は全部「導出」。金額に代入している行は1つもない\nconst subtotal = $$.computed(() => {\n  return items().reduce((sum, item) => sum + item.unit * item.qty, 0);\n});\n\nconst shipping = $$.computed(() => {\n  if (subtotal() === 0) return 0;\n\n  return subtotal() >= FREE_SHIPPING_FROM ? 0 : SHIPPING_FEE;\n});\n\nconst discount = $$.computed(() => {\n  return useCoupon() ? Math.floor(subtotal() * COUPON_RATE) : 0;\n});\n\nconst taxable = $$.computed(() => subtotal() - discount() + shipping());\nconst tax = $$.computed(() => Math.floor(taxable() * TAX_RATE));\nconst total = $$.computed(() => taxable() + tax());\nconst amountToFreeShipping = $$.computed(() => {\n  return Math.max(0, FREE_SHIPPING_FROM - subtotal());\n});\n\nconst changeQuantity = (id, change) => {\n  items((list) =>\n    list.map((item) => {\n      if (item.id !== id) return item;\n\n      return { ...item, qty: Math.max(1, change(item.qty)) };\n    })\n  );\n};\n\nconst removeItem = (id) => {\n  items((list) => list.filter((item) => item.id !== id));\n};\n\n$el.find(\"@rows\").repeat(items, {\n  key: (item) => item.id,\n  tpl: \"@row-tpl\",\n  render: ($row, item) => {\n    $row.find(\"@name\").text(item.name);\n    $row.find(\"@unit\").text(item.unit, $$.money, \"円\");\n    $row.find(\"@qty\").text(item.qty);\n    $row.find(\"@line\").text(item.unit * item.qty, $$.money, \"円\");\n\n    $row.find(\"@inc\").click(() => changeQuantity(item.id, (qty) => qty + 1));\n    $row.find(\"@dec\").click(() => changeQuantity(item.id, (qty) => qty - 1));\n    $row.find(\"@del\").click(() => removeItem(item.id));\n  },\n});\n\nconst isEmpty = $$.computed(() => items().length === 0);\n\n$el.find(\"@empty\").when(isEmpty);\n$el.find(\"@summary\").when(() => !isEmpty());\n$el.find(\"@subtotal\").text(subtotal, $$.money, \"円\");\n$el.find(\"@ship\").text(shipping, (fee) => {\n  return fee === 0 ? \"無料\" : `${$$.money(fee)}円`;\n});\n$el.find(\"@discount\").text(discount, (amount) => {\n  return amount === 0 ? \"—\" : `-${$$.money(amount)}円`;\n});\n$el.find(\"@tax\").text(tax, $$.money, \"円\");\n$el.find(\"@total\").text(total, $$.money);\n$el.find(\"@to-free\").text(amountToFreeShipping, $$.money);\n$el.find(\"@free-note\").when(() => {\n  return amountToFreeShipping() > 0 && !isEmpty();\n});\n\n$el.find(\"@restore\").click(() => {\n  items(CART_ITEMS.map((item) => ({ ...item })));\n});","html":"<div class=\"card\" data-component=\"ex-cart\">\n        <ul class=\"ex-opts\" data-brg=\"rows\" style=\"gap:2px\"></ul>\n        <template data-brg=\"row-tpl\">\n          <li data-brg=\"row\" style=\"gap:12px\">\n            <span data-brg=\"name\" style=\"flex:1\"></span>\n            <span class=\"ex-hidden-note\" data-brg=\"unit\"></span>\n            <span class=\"ex-qty\" style=\"display:inline-flex;align-items:center;gap:8px\">\n              <button type=\"button\" data-brg=\"dec\" aria-label=\"減らす\">−</button>\n              <b data-brg=\"qty\" style=\"min-width:1.6em;text-align:center\"></b>\n              <button type=\"button\" data-brg=\"inc\" aria-label=\"増やす\">＋</button>\n            </span>\n            <span data-brg=\"line\" style=\"min-width:5.5em;text-align:right\"></span>\n            <button type=\"button\" data-brg=\"del\" aria-label=\"削除\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:18px 0\">\n          カートは空です\n        </p>\n\n        <div data-brg=\"summary\">\n          <div class=\"ex-total\"><span>小計</span><span data-brg=\"subtotal\"></span></div>\n          <div class=\"ex-total\"><span data-brg=\"ship-label\">送料</span><span data-brg=\"ship\"></span></div>\n          <div class=\"ex-total\"><span>クーポン</span><span data-brg=\"discount\"></span></div>\n          <div class=\"ex-total\"><span>消費税（10%）</span><span data-brg=\"tax\"></span></div>\n          <div class=\"ex-total\" style=\"border-top:2px solid var(--line)\">\n            <b>合計</b>\n            <strong class=\"ex-price\"><span data-brg=\"total\"></span><small>円</small></strong>\n          </div>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:14px\">\n          <label><input type=\"checkbox\" data-brg=\"coupon\"> クーポンを使う（10% OFF）</label>\n          <button type=\"button\" class=\"btn ghost\" data-brg=\"restore\" style=\"font-size:13px\">商品を戻す</button>\n        </div>\n        <p class=\"ex-hidden-note\" data-brg=\"free-note\">"},"todo":{"js":"let nextId = 3;\n\nconst todos = $$.state([\n  { id: 1, title: \"見積書を送る\", done: false },\n  { id: 2, title: \"請求書を確認する\", done: true },\n]);\n\nconst filter = $el.find(\"@filter\").group();\nconst draft = $el.find(\"@input\").state(\"\");\n\n// 表示する一覧は「絞り込んだ結果」を導出する\nconst visibleTodos = $$.computed(() => {\n  if (filter() === \"open\") return todos().filter((todo) => !todo.done);\n  if (filter() === \"done\") return todos().filter((todo) => todo.done);\n\n  return todos();\n});\n\nconst remainingCount = $$.computed(() => {\n  return todos().filter((todo) => !todo.done).length;\n});\n\nconst addTodo = () => {\n  const title = draft().trim();\n  if (!title) return;\n\n  todos((list) => [...list, { id: nextId++, title, done: false }]);\n  draft(\"\");\n};\n\nconst setDone = (id, done) => {\n  todos((list) =>\n    list.map((todo) => {\n      if (todo.id !== id) return todo;\n\n      return { ...todo, done };\n    })\n  );\n};\n\n$el.find(\"@add\").click(addTodo);\n$el.find(\"@input\").on(\"keydown\", (event) => {\n  if (event.key !== \"Enter\") return;\n\n  event.preventDefault();\n  addTodo();\n});\n\n$el.find(\"@counts\").text(remainingCount, \"件が未完了\");\n$el.find(\"@empty\").when(() => visibleTodos().length === 0);\n\n$el.find(\"@list\").repeat(visibleTodos, {\n  key: (todo) => todo.id,\n  tpl: \"@todo-tpl\",\n  render: ($row, todo) => {\n    $row.find(\"@title\").text(todo.title);\n    $row.find(\"@check\").prop(\"checked\", todo.done);\n\n    $row.find(\"@check\").on(\"change\", function () {\n      setDone(todo.id, this.checked);\n    });\n    $row.find(\"@del\").click(() => {\n      todos((list) => list.filter((item) => item.id !== todo.id));\n    });\n\n    $row.selected(() => todo.done);\n  },\n});","html":"<div class=\"card\" data-component=\"ex-todo\">\n        <div class=\"ex-inline\" style=\"gap:8px\">\n          <input type=\"text\" data-brg=\"input\" placeholder=\"やることを入力して Enter\"\n                 style=\"flex:1;min-width:12em;padding:9px 11px;border:1px solid var(--line);border-radius:8px;background:transparent;color:inherit;font:inherit\">\n          <button type=\"button\" class=\"btn primary\" data-brg=\"add\" style=\"font-size:13px\">追加</button>\n        </div>\n\n        <div class=\"ex-inline\" style=\"margin-top:12px\">\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"all\" data-brg=\"filter\" checked> すべて</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"open\" data-brg=\"filter\"> 未完了</label>\n          <label><input type=\"radio\" name=\"todo-filter\" value=\"done\" data-brg=\"filter\"> 完了</label>\n          <span class=\"ex-hidden-note\" data-brg=\"counts\"></span>\n        </div>\n\n        <ul class=\"ex-opts\" data-brg=\"list\" style=\"margin-top:10px\"></ul>\n        <template data-brg=\"todo-tpl\">\n          <li data-brg=\"item\">\n            <input type=\"checkbox\" data-brg=\"check\">\n            <span data-brg=\"title\" style=\"flex:1\"></span>\n            <input type=\"text\" data-brg=\"memo\" placeholder=\"メモ\"\n                   style=\"width:9em;padding:5px 8px;border:1px solid var(--line);border-radius:6px;background:transparent;color:inherit;font:inherit;font-size:12px\">\n            <button type=\"button\" data-brg=\"del\">×</button>\n          </li>\n        </template>\n\n        <p data-brg=\"empty\" style=\"text-align:center;color:var(--muted);padding:14px 0\">該当するものがありません</p>"}};
